const since = new Date(Date.now() - 14 * 86400000).toISOString().slice(0, 19) + 'Z';
return [{
  json: {
    ukGovUrl: `https://www.contractsfinder.service.gov.uk/Published/Notices/OCDS/Search?publishedFrom=${encodeURIComponent(since)}&stages=tender,award&limit=15`,
    clinicalTrialsUrl: 'https://clinicaltrials.gov/api/v2/studies?query.cond=oncology&filter.overallStatus=RECRUITING&filter.advanced=AREA%5BLeadSponsorClass%5DINDUSTRY&pageSize=10',
  },
}];

// Merge and normalize UK Gov Tenders + ClinicalTrials.gov Industry leads into one CRM schema
const ukItems = $('Fetch UK Gov Tenders OCDS').all();
const ctItems = $('Fetch ClinicalTrials v2 Studies').all();
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const leads = [];

for (const item of ukItems) {
  const releases = Array.isArray((item.json || {}).releases) ? item.json.releases : [];
  for (const rel of releases) {
    const tender = rel.tender || {};
    const parties = Array.isArray(rel.parties) ? rel.parties : [];
    const buyer = parties.find((p) => Array.isArray(p.roles) && (p.roles.includes('buyer') || p.roles.includes('procuringEntity'))) || parties[0] || {};
    const contact = buyer.contactPoint || {};
    const val = tender.value || tender.minValue || {};
    const rawId = String(rel.id || '');
    const uuidCandidate = rawId.includes('-') ? rawId.replace(/-[^-]+$/, '') : rawId;
    const sourceUrl = uuidRe.test(uuidCandidate)
      ? `https://www.contractsfinder.service.gov.uk/Notice/${uuidCandidate}`
      : 'https://www.contractsfinder.service.gov.uk/';

    leads.push({
      json: {
        leadSource: 'uk-contracts-finder',
        externalId: rel.ocid || rawId,
        organization: String(buyer.name || (rel.buyer || {}).name || '').trim(),
        contactName: contact.name ? String(contact.name).trim() : null,
        contactEmail: contact.email ? String(contact.email).trim() : null,
        opportunityTitle: String(tender.title || '').trim(),
        metricLabel: typeof val.amount === 'number' ? `GBP ${val.amount.toLocaleString('en-US')}` : null,
        deadlineOrPhase: String((tender.tenderPeriod || {}).endDate || '').slice(0, 10) || null,
        sourceUrl,
      },
    });
  }
}

for (const item of ctItems) {
  const studies = Array.isArray((item.json || {}).studies) ? item.json.studies : [];
  for (const st of studies) {
    const ps = st.protocolSection || {};
    const ident = ps.identificationModule || {};
    const sponsor = (ps.sponsorCollaboratorsModule || {}).leadSponsor || {};
    const design = ps.designModule || {};
    const contacts = (ps.contactsLocationsModule || {}).centralContacts || [];
    const primary = contacts.find((c) => c && c.email) || contacts[0] || {};
    const nctId = ident.nctId || '';
    leads.push({
      json: {
        leadSource: 'clinicaltrials-gov-v2',
        externalId: nctId,
        organization: sponsor.name || '',
        contactName: primary.name || null,
        contactEmail: primary.email || null,
        opportunityTitle: ident.briefTitle || '',
        metricLabel: (design.enrollmentInfo || {}).count ? `Enrollment ${design.enrollmentInfo.count}` : null,
        deadlineOrPhase: (design.phases || []).join(', ') || null,
        sourceUrl: nctId ? `https://clinicaltrials.gov/study/${nctId}` : 'https://clinicaltrials.gov/',
      },
    });
  }
}

return leads.length ? leads : [{ json: { status: 'no_leads_returned' } }];
